import PropTypes from 'prop-types';
import { useFormik } from 'formik';
import {
    Grid,
    Button,
    TextField,
    MenuItem,
    Switch,
    FormControlLabel,
    Autocomplete,
    InputAdornment,
    CircularProgress,
    Collapse,
    Paper
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import RestartAltIcon from '@mui/icons-material/RestartAlt';
import { useTheme, styled } from '@mui/material/styles';

// Styled container for filter form
const FilterContainer = styled(Paper)(({ theme }) => ({
    padding: theme.spacing(4),
    background: '#F2F7F8',
    borderRadius: theme.shape.borderRadius,
    boxShadow: theme.shadows[3]
}));

/**
 * **GenericSearchFilter (Manual Search & Filtering)**
 * - **No debounce**: Runs only when clicking **Search**.
 */
const GenericSearchFilter = ({
    fields,
    onSearch,
    onFilter, // ✅ Now supports filtering
    onReset,
    searchValues,
    setSearchValues,
    expanded,
    setExpanded,
    loading
}) => {
    const theme = useTheme();

    // ✅ Formik for managing form state
    const formik = useFormik({
        initialValues: searchValues || {}, // ✅ Uses initial search values
        enableReinitialize: true,
        onSubmit: (values) => {
            console.log('🔍 Manual search triggered:', values);
            onSearch(values); // ✅ Calls API with search params
            // setExpanded(false);
        }
    });

    // ✅ Reset Filters & API Data
    const handleReset = () => {
        formik.resetForm({ values: {} });
        setSearchValues({});
        onReset(); // ✅ Call dedicated reset handler
    };
    return (
        <Collapse in={expanded} timeout="auto">
            <FilterContainer>
                <form onSubmit={formik.handleSubmit}>
                    <Grid container spacing={2}>
                        {fields.map((field) => (
                            <Grid item xs={12} sm={6} key={field.name}>
                                {(() => {
                                    switch (field.type) {
                                        case 'select':
                                            return (
                                                <TextField
                                                    select
                                                    fullWidth
                                                    name={field.name}
                                                    label={field.label}
                                                    value={formik.values[field.name] || ''}
                                                    onChange={formik.handleChange}
                                                    variant="outlined"
                                                >
                                                    {field.options.map((option) => (
                                                        <MenuItem key={option.value} value={option.value}>
                                                            {option.label}
                                                        </MenuItem>
                                                    ))}
                                                </TextField>
                                            );

                                        case 'autocomplete':
                                            return (
                                                <Autocomplete
                                                    options={field.options || []}
                                                    getOptionLabel={(option) => option.label}
                                                    value={formik.values[field.name] || null}
                                                    onChange={(event, newValue) => formik.setFieldValue(field.name, newValue)}
                                                    renderInput={(params) => (
                                                        <TextField
                                                            {...params}
                                                            label={field.label}
                                                            fullWidth
                                                            variant="outlined"
                                                            InputProps={{
                                                                ...params.InputProps,
                                                                endAdornment: (
                                                                    <>
                                                                        {loading && <CircularProgress color="inherit" size={20} />}
                                                                        {params.InputProps.endAdornment}
                                                                    </>
                                                                )
                                                            }}
                                                        />
                                                    )}
                                                />
                                            );

                                        case 'switch':
                                            return (
                                                <FormControlLabel
                                                    control={
                                                        <Switch
                                                            checked={Boolean(formik.values[field.name])}
                                                            onChange={(e) => formik.setFieldValue(field.name, e.target.checked)}
                                                        />
                                                    }
                                                    label={field.label}
                                                    sx={{
                                                        '&& .MuiFormControlLabel-label': {
                                                            // Double '&' boosts priority
                                                            color: 'primary.dark',
                                                            width: '100%'
                                                        }
                                                    }}
                                                />
                                            );

                                        case 'date':
                                            return (
                                                <TextField
                                                    fullWidth
                                                    name={field.name}
                                                    label={field.label}
                                                    type="date"
                                                    value={formik.values[field.name] || ''}
                                                    onChange={formik.handleChange}
                                                    InputLabelProps={{ shrink: true }}
                                                    variant="outlined"
                                                />
                                            );

                                        default:
                                            return (
                                                <TextField
                                                    fullWidth
                                                    name={field.name}
                                                    label={field.label}
                                                    type={field.type || 'text'}
                                                    value={formik.values[field.name] || ''}
                                                    onChange={formik.handleChange}
                                                    InputProps={{
                                                        startAdornment: field.type === 'search' && (
                                                            <InputAdornment position="start">
                                                                <SearchIcon />
                                                            </InputAdornment>
                                                        )
                                                    }}
                                                    variant="outlined"
                                                    sx={{
                                                        '& .MuiInputLabel-root': {
                                                            borderColor: 'rgba(0, 0, 0, 0.23)',
                                                            color: 'primary.dark', // Custom gray color
                                                            '&.Mui-focused': {
                                                                color: 'primary.dark' // Blue when focused (matches MUI primary)
                                                            },
                                                            '&.Mui-error': {
                                                                color: 'primary.dark' // Red when there's an error
                                                            }
                                                        },
                                                        '& .MuiOutlinedInput-root': {
                                                            '&:hover .MuiOutlinedInput-notchedOutline': {
                                                                borderColor: 'rgba(0, 0, 0, 0.23)'
                                                                // Default border color (or your preferred color)
                                                            }
                                                        }
                                                    }}
                                                />
                                            );
                                    }
                                })()}
                            </Grid>
                        ))}
                    </Grid>

                    {/* Search & Reset Buttons */}
                    <Grid container justifyContent="flex-end" sx={{ mt: 2 }}>
                        <Button startIcon={<RestartAltIcon />} onClick={handleReset} color="secondary" variant="outlined" sx={{ mr: 1 }}>
                            Reset
                        </Button>
                        <Button startIcon={<SearchIcon />} type="submit" variant="contained" color="primary">
                            Search
                        </Button>
                    </Grid>
                </form>
            </FilterContainer>
        </Collapse>
    );
};

// ✅ Updated Prop Types
GenericSearchFilter.propTypes = {
    fields: PropTypes.arrayOf(
        PropTypes.shape({
            name: PropTypes.string.isRequired,
            label: PropTypes.string.isRequired,
            type: PropTypes.oneOf(['text', 'select', 'autocomplete', 'switch', 'date']),
            options: PropTypes.array // Only for select/autocomplete fields
        })
    ).isRequired,
    onSearch: PropTypes.func.isRequired,
    onFilter: PropTypes.func.isRequired, // ✅ Now supports filtering
    searchValues: PropTypes.object,
    setSearchValues: PropTypes.func.isRequired, // ✅ Stores search params
    expanded: PropTypes.bool.isRequired,
    setExpanded: PropTypes.func.isRequired,
    loading: PropTypes.bool,
    onReset: PropTypes.func.isRequired
};

export default GenericSearchFilter;
